C='Restaurant schema CUSTOMER(CustomerID,FirstName,Surname,Phone,Email);ORDER(OrderID,OrderDate,OrderTime,CustomerID);ORDERLINE(OrderID,ItemID,Quantity,UnitPrice,LinePrice);ITEM(ItemID,Name,QtyInStock,UnitPrice).'
e(1,'a',3,4,'Outline','Outline two reasons why the restaurant would use a database to store this information rather than a spreadsheet.',C,['A3.1.1'],'A',4,'Structured relationships/integrity,concurrent use,query capability;two reasons and expansions.','A repair centre stores clients,jobs and replacement parts. Outline two advantages of a relational database over separate spreadsheets for this information.',pts((1,'Related records can be connected using keys.'),(1,'Referential constraints help maintain valid client/job/part relationships.'),(1,'Concurrent access can be controlled.'),(1,'Several staff can update records with reduced risk of inconsistent competing edits.')))
e(1,'b',3,2,'Outline','Outline one benefit of storing the data in the DateOfVisit field in the order of yyyy/mm/dd.',C,['A3.2.3'],'B',4,'Year-first text dates sort chronologically and are less ambiguous;standard interoperability.','A database imports dates from offices in several countries. Outline why using one consistent date representation matters.',pts((1,'A consistent representation avoids interpreting a day as a month or vice versa.'),(1,'This improves comparison,sorting and data integrity when records are combined.')),reason='Retains data consistency reasoning without requiring a particular ISO standard or assuming text dates equal native date types.')
e(1,'c',3,3,'Outline','Outline the reason for using OrderID and ItemID instead of OrderlineID as the primary key.',C,['A3.1.1','A3.2.4'],'A',4,'Composite key identifies a line by natural order/item pair,avoids extra surrogate field.','A ticket sale has SaleID and ProductID. Each product may occur only once in a sale,with quantity stored separately. Outline why (SaleID,ProductID) can be a suitable composite primary key.',pts((1,'Neither SaleID nor ProductID is individually unique across all lines.'),(1,'Their combination uniquely identifies one product line in one sale.'),(1,'The key enforces the one-line-per-product-per-sale rule without an extra line identifier.')))
e(1,'d',3,2,'Outline','Outline one potential issue that this may create when writing a query for data interrogation.',C+'UnitPrice occurs in both ORDERLINE and ITEM.',['A3.3.2'],'A',4,'Unqualified UnitPrice ambiguous;qualify with table name.','Two joined tables InvoiceLine and Product both contain UnitPrice. Outline why SELECT UnitPrice may fail and how to remove the ambiguity.',pts((1,'The unqualified column name does not identify which table’s price is required.'),(1,'Qualify it,e.g.InvoiceLine.UnitPrice,or use a table alias.')))
sql='SELECT b.FirstName,b.Surname,i.InvoiceDate FROM Buyer AS b JOIN Invoice AS i ON b.BuyerID=i.BuyerID WHERE b.FirstName=\'Mira\' AND b.Surname=\'Shah\';'
e(1,'e',3,4,'Identify','Identify the steps to create a query to list the visits of a customer with first name Akemi and surname Watene. Display FirstName,Surname and OrderDate.',C,['A3.3.2'],'B',5,'Select fields;join customer/order by PK-FK;filter both names.','Construct an SQL query using Buyer(BuyerID,FirstName,Surname) and Invoice(InvoiceID,BuyerID,InvoiceDate). Return first name,surname and invoice date for buyer Mira Shah.',pts((1,'Selects the three requested fields.'),(1,'Uses Buyer and Invoice.'),(1,'Joins on matching BuyerID values.'),(1,'Filters both FirstName=Mira and Surname=Shah using AND.')),solution=sql,reason='Preserves two-table join/filter reasoning;new schema avoids reserved ORDER identifier and source sample’s OrdDate/OrderDate mismatch.')
e(2,'a',4,3,'Explain','Explain why the decision to delete the LinePrice field has been made.',C+'LinePrice=Quantity×UnitPrice.',['A3.2.5'],'A',5,'Derived field duplicates calculable data and risks inconsistency.','An invoice line stores Quantity,PriceEach and LineTotal=Quantity×PriceEach. Explain why storing LineTotal can create a consistency problem.',pts((1,'LineTotal can be calculated from the other two stored values.'),(1,'If either input changes but LineTotal is not updated,the row contains contradictory values.'),(1,'Calculating it when needed avoids that redundant update obligation.')))
e(2,'b',4,1,'Define','Define the term database transaction.','Shift manager records hours and pay as one transaction.',['A3.3.6'],'A',5,'Logical unit of work completed wholly or not at all.','Define a database transaction.',pts((1,'A logical unit of database operations treated as one complete operation that commits or rolls back.')))
e(2,'c-i',4,1,'State','State one way to validate the hours_worked field.','',['A3.2.3'],'B',5,'Range,type or presence check.','State a suitable data type for a field storing hours worked,including fractional hours.',pts((1,'A decimal/numeric or appropriate real-number type.')),reason='Retains data-type suitability subset;generic catalogue of validation checks is not imported as database scope.')
e(2,'c-ii',4,2,'Outline','Outline one way to verify the payrate field.','',[],'C',5,'Compare source record or double-entry verification.','',reason='Data-entry verification methods are not a2027 requirement;do not relabel them database data types or ML cleaning.')
e(2,'d',4,4,'Explain','Explain how data integrity can be maintained if an employee tries to access their work hours while the shift manager is editing them.','Concurrent reads/edits of shift record.',['A3.3.6'],'A',5,'Lock record or use coherent version;isolate edit until completed.','Explain how transaction isolation can protect a payroll record while one user updates hours and another reads it.',pts((1,'The update is performed within a transaction.'),(1,'Other users must not see a partially applied update.'),(1,'A suitable locking/version mechanism presents a consistent record or delays access.'),(1,'Commit exposes the completed state;rollback restores the previous valid state after failure.')))
e(2,'e',4,4,'Describe','Describe one alternative method that could be used to recover a database after a crash has occurred.','Alternative to transaction-log recovery.',['A3.3.6'],'B',6,'Snapshot recovery or rollback interrupted transactions.','Describe what should happen to an uncommitted transaction interrupted by a database failure,using a transfer that debits one account and credits another.',pts((1,'Treat both changes as one transaction.'),(1,'If the transaction was not committed,undo its partial changes.'),(1,'Restore balances to the consistent pre-transaction state.'),(1,'A completed committed transfer must remain durable rather than losing one side of the transfer.')),reason='Narrows detailed backup/recovery-method taxonomy to explicit ACID atomicity,durability and rollback.')
